-- Hunters' starting weapon skills for every race now come from classicplus_weapons.sql
-- (raceMask 0 rows), so the stock race-specific rows are left alone. (An UPDATE here was not
-- safe to re-run: it collided with its own earlier result.)

-- Base stats (player_levelstats) for every new combo. Without them the world server refuses to
-- start ("Race 1 Class 3 Level 1 does not have stats data!"). Each new combo takes its class's
-- stats from a race that already has that class, shifted by the two races' difference measured on
-- Warriors (every vanilla race has Warriors). INSERT IGNORE: existing rows are never touched.
INSERT IGNORE INTO player_levelstats (race, class, level, str, agi, sta, inte, spi)
SELECT pc.race, pc.class, s.level,
       GREATEST(1, s.str  + w.str  - ws.str),
       GREATEST(1, s.agi  + w.agi  - ws.agi),
       GREATEST(1, s.sta  + w.sta  - ws.sta),
       GREATEST(1, s.inte + w.inte - ws.inte),
       GREATEST(1, s.spi  + w.spi  - ws.spi)
FROM playercreateinfo pc
JOIN (SELECT class, MIN(race) AS src FROM player_levelstats GROUP BY class) pick ON pick.class = pc.class
JOIN player_levelstats s  ON s.race = pick.src AND s.class = pc.class
JOIN player_levelstats w  ON w.race = pc.race  AND w.class = 1 AND w.level = s.level
JOIN player_levelstats ws ON ws.race = pick.src AND ws.class = 1 AND ws.level = s.level;

-- Combos modern WoW does not have, which an earlier Open Vanilla build allowed (Tauren Paladin and Dwarf
-- Shaman since the 56-combo set). They are removed unless a character already uses one (that
-- character would otherwise fail to load); the SELECT below lists any that were kept for that reason.
DELETE FROM playercreateinfo_spell  WHERE (race,class) IN ((1,7),(1,11),(2,2),(2,11),(3,11),(4,2),(4,7),(5,2),(5,7),(5,11),(7,2),(7,7),(7,11),(8,2),(6,2),(3,7))
  AND (race,class) NOT IN (SELECT race,class FROM classiccharacters.characters);
DELETE FROM playercreateinfo_action WHERE (race,class) IN ((1,7),(1,11),(2,2),(2,11),(3,11),(4,2),(4,7),(5,2),(5,7),(5,11),(7,2),(7,7),(7,11),(8,2),(6,2),(3,7))
  AND (race,class) NOT IN (SELECT race,class FROM classiccharacters.characters);
DELETE FROM player_levelstats       WHERE (race,class) IN ((1,7),(1,11),(2,2),(2,11),(3,11),(4,2),(4,7),(5,2),(5,7),(5,11),(7,2),(7,7),(7,11),(8,2),(6,2),(3,7))
  AND (race,class) NOT IN (SELECT race,class FROM classiccharacters.characters);
DELETE FROM playercreateinfo        WHERE (race,class) IN ((1,7),(1,11),(2,2),(2,11),(3,11),(4,2),(4,7),(5,2),(5,7),(5,11),(7,2),(7,7),(7,11),(8,2),(6,2),(3,7))
  AND (race,class) NOT IN (SELECT race,class FROM classiccharacters.characters);
SELECT race, class, COUNT(*) AS characters_keeping_a_retired_combo FROM classiccharacters.characters
  WHERE (race,class) IN ((1,7),(1,11),(2,2),(2,11),(3,11),(4,2),(4,7),(5,2),(5,7),(5,11),(7,2),(7,7),(7,11),(8,2),(6,2),(3,7)) GROUP BY race, class;

-- A retired combo kept for its characters still must not take new ones: the world server
-- (OpenVanilla.ClosedCombos) refuses to create characters of the pairs listed here.
CREATE TABLE IF NOT EXISTS openvanilla_closed_combo (
  race   TINYINT UNSIGNED NOT NULL,
  class  TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (race, class)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Open Vanilla: no new characters of these race/class pairs';
INSERT IGNORE INTO openvanilla_closed_combo (race, class) VALUES (1,7),(1,11),(2,2),(2,11),(3,11),(4,2),(4,7),(5,2),(5,7),(5,11),(7,2),(7,7),(7,11),(8,2),(6,2),(3,7);
